def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) > 2 and opp.get('budget', 0) > DAILY_SALARY * 0.8:
                    threat_bids.append(float(bid))

    if not alive:
        return float(min(budget, 1.0))

    competitors = 1 + len(alive)
    ample_supply = supply >= competitors * WATER_REQ
    very_tight = supply <= WATER_REQ * 1.35
    tight = supply <= WATER_REQ * 1.7

    highest_prev = max(prev_bids) if prev_bids else 0.0
    core_threat = max(threat_bids) if threat_bids else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    if ample_supply and urgency == 0:
        base = 6.0
    elif ample_supply:
        base = 14.0 + 6.0 * urgency
    elif very_tight:
        base = max(48.0, core_threat + 6.0)
    elif tight:
        base = max(34.0, core_threat + 3.0)
    else:
        base = max(20.0, core_threat * 0.72)

    if desperate_count >= 2 and not ample_supply:
        base += 8.0
    elif desperate_count == 0 and ample_supply:
        base -= 3.0

    if urgency >= 5:
        base = max(base, 66.0)
    elif urgency >= 3:
        base = max(base, 52.0)
    elif urgency >= 2:
        base = max(base, 38.0)

    reserve_days = max(0, 10 - day)
    soft_cap = budget if reserve_days <= 1 else max(0.0, budget - reserve_days * 6.0)
    bid = min(base, budget)
    if soft_cap > 0:
        bid = min(bid, max(base * 0.9, soft_cap))

    if hp <= 1 or no_water >= 2:
        bid = min(budget, max(bid, core_threat + 10.0, 69.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Basic safety
    if my_status['budget'] <= 0:
        return 0.0

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    alive_opps = [o for o in opponents_status.values() if o.get('alive', True)]
    if not alive_opps:
        # If alone, bid just enough to secure survival when needed
        target = DAILY_SALARY * (0.35 if my_status['hp'] > 3 else 0.85)
        return float(min(my_status['budget'], target))

    # Read yesterday bids from traces to infer aggressiveness
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If we have trace info, respond to the highest pressure
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Cindy shows willingness to overpay; treat very high bids as a signal to not chase blindly.
        # Instead, bid to stay competitive when our hp is low.
        if my_status['hp'] <= 2:
            # Must secure water; bid aggressively but cap by budget.
            # If others were bidding very high yesterday, we still try a strong bid.
            bid = DAILY_SALARY * (0.95 if highest_prev_bid < DAILY_SALARY * 2 else 0.85)
            return float(min(my_status['budget'], bid))
        elif my_status['hp'] == 3:
            # Medium urgency: bid around 0.65-0.75 of salary depending on pressure.
            bid = DAILY_SALARY * (0.75 if highest_prev_bid < DAILY_SALARY * 1.5 else 0.68)
            return float(min(my_status['budget'], bid))
        else:
            # Comfortable: bid modestly; if pressure was high, slightly increase.
            bid = DAILY_SALARY * (0.55 if highest_prev_bid < DAILY_SALARY * 1.5 else 0.62)
            return float(min(my_status['budget'], bid))

    # Fallback when no trace bids available
    if my_status['hp'] <= 2:
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))
    return float(min(my_status['budget'], DAILY_SALARY * 0.55))

def get_bid(day_context, my_status, opponents_status):
    EPISODE_DAYS = 10
    WATER_REQ = 13
    DAILY_SALARY = 150

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, 1.0) if my_budget > 0 else 0.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid_percentage = 0.6

    if my_hp <= 2:
        base_bid_percentage = 1.1
    elif my_hp <= 4:
        base_bid_percentage = 0.9
    elif my_no_water_days > 0:
        base_bid_percentage = max(base_bid_percentage, 0.75)

    my_calculated_bid = DAILY_SALARY * base_bid_percentage

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

        if my_hp <= 2:
            my_calculated_bid = max(my_calculated_bid, max_prev_bid + 10.0)
        elif my_hp <= 4:
            my_calculated_bid = max(my_calculated_bid, max_prev_bid + 5.0)
        else:
            my_calculated_bid = max(my_calculated_bid, max_prev_bid + 2.0)

        my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.4)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp > 0:
        my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 1.0)

    final_bid = min(my_budget, my_calculated_bid)

    if my_budget > 0:
        final_bid = max(final_bid, 1.0)
    else:
        final_bid = 0.0

    return final_bid

